// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: an address 'from', an uint256 v, and a dynamic array length encoded via uint256 n
    // We cannot fuzz an address for the callee because an EOA always accepts calls and records nothing;
    // so we deploy a Recorder callee and pass its address. We still fuzz 'from', 'v', and the number of tos.
    function testFuzz_property(address from, uint256 v, uint256 n) public {
        // Keep n reasonably bounded to avoid huge loops while staying wide.
        uint256 len = bound(n, 1, 10); // require non-empty _tos so reference should accept for all admissible inputs

        // Build a tos array of length 'len' with distinct addresses derived from 'from' and index
        address[] memory tos = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            // deterministic pseudo-addresses derived from 'from' and index
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // Deploy a Recorder that implements transferFrom(address,address,uint256)
        Recorder recorder = new Recorder();

        // Call transfer on c and observe whether it reverts. The reference C must accept (not revert) when _tos.length > 0.
        bool ok;
        try c.transfer(from, address(recorder), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for every admissible input with non-empty _tos, reference C does not revert and calls the callee exactly len times.
        // We assert this: ok must be true and recorder.callCount() must equal len.
        // This holds for the reference implementation for all admissible inputs; the mutant that requires _tos.length == 0 will revert for these inputs.
        assertTrue(ok);
        assertTrue(recorder.callCount() == len);
    }
}

// Recorder that exposes the exact function selector the contract encodes with
contract Recorder {
    // count how many times transferFrom was called and record last args
    uint256 public calls;
    mapping(uint256 => address) public tos;
    mapping(uint256 => address) public froms;
    mapping(uint256 => uint256) public vals;

    // This matches bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        tos[calls] = to;
        froms[calls] = from;
        vals[calls] = v;
        calls += 1;
        return true;
    }

    function callCount() external view returns (uint256) { return calls; }
}
